create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_FACT_STORE_OPEN_DAYS (
	BUS_DT DATE NOT NULL COMMENT 'The business date for which the store status is tracked.',
	STORE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a store.',
	REAL_ESTATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the real estate object.',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the business country for which the related country organization is responsible. (The business country is not identical to a political country.)',
	STORE_OPEN_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the store was actually open on the given day.',
	STORE_OPEN_DAYS_BYTD_CNT NUMBER(38,0) NOT NULL COMMENT 'The number of days this store has already been open in the current business year. (the business-year-to-date count of the store_open_fg)',
	STORE_OPEN_PY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the store was actually open on the same calendar date one year ago.',
	STORE_OPEN_DAYS_PY_BYTD_CNT NUMBER(38,0) NOT NULL COMMENT 'The number of days this store has been open in the previous business year up to the equivalent calendar date one year ago.  (the business-year-to-date count of the store_open_py_fg)',
	STORE_OPEN_PY_SWDAY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the store was actually open on the same weekday one year ago.',
	STORE_OPEN_DAYS_PY_SWDAY_BYTD_CNT NUMBER(38,0) NOT NULL COMMENT 'The number of days this store has been open in the previous business year up to the equivalent weekday one year ago.  (the business-year-to-date count of the store_open_py_swday_fg)',
	RELEVANT_FOR_COMP_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the revenue, which this store made on the given business date, can be compared with its revenue on the equivalent day in the year before. When comparing the revenue, the growth that is caused purely by the increase in  the number of stores, shall be excluded. (bereinigte Steigerung) So this indicator is set to FALSE for the first year after the opening of a new store, i.e. for the days between the opening date and the Sunday following the corresponding day in the next year.',
	RELEVANT_FOR_COMP_PY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the revenue, which this store made on the same calendar date one year ago, can be compared with its revenue in the year before (i.e. two years ago). When comparing the revenue, the growth that is caused purely by the increase in  the number of stores, shall be excluded. (bereinigte Steigerung) So this indicator is set to FALSE for the first year after the opening of a new store, i.e. for the days between the opening date and the Sunday following the corresponding day in the next year.',
	RELEVANT_FOR_COMP_PY_SWDAY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the revenue, which this store made on the same weekday date one year ago, can be compared with its revenue in the year before (i.e. two years ago). When comparing the revenue, the growth that is caused purely by the increase in  the number of stores, shall be excluded. (bereinigte Steigerung) So this indicator is set to FALSE for the first year after the opening of a new store, i.e. for the days between the opening date and the Sunday following the corresponding day in the next year.',
	OPEN_TM TIME(9) COMMENT 'The time (in the local time zone) when the store opened.',
	CLOSE_TM TIME(9) COMMENT 'The time (in the local time zone) when the store closed.',
	OPEN_HR_CNT NUMBER(38,2) COMMENT 'The number of hours the store was open on the given date.',
	OPEN_HR_BYTD_CNT NUMBER(38,2) COMMENT 'The business-year-to-date sum of the number of hours the store has been open up to the given date.',
	OPEN_HR_PY_CNT NUMBER(38,2) COMMENT 'The number of hours the store was open on the equivalent calendar date one year ago.',
	OPEN_HR_PY_BYTD_CNT NUMBER(38,2) COMMENT 'The business-year-to-date sum of the hours the store has been open up to the equivalent calendar date one year ago.',
	OPEN_HR_PY_SWDAY_CNT NUMBER(38,2) COMMENT 'The number of hours the store was open on the equivalent weekday one year ago.',
	OPEN_HR_PY_SWDAY_BYTD_CNT NUMBER(38,2) COMMENT 'The business-year-to-date sum of the hours the store has been open up to the equivalent weekday one year ago.',
	EMP_HR_CNT NUMBER(38,2) COMMENT 'The number of hours, employees have worked in this store on the given day.',
	EMP_HR_BYTD_CNT NUMBER(38,2) COMMENT 'The business-year-to-date sum of the number of hours, employees have worked in this store up to the given date.',
	EMP_HR_PY_CNT NUMBER(38,2) COMMENT 'The number of hours, employees have worked in this store on the equivalent calendar date one year ago.',
	EMP_HR_PY_BYTD_CNT NUMBER(38,2) COMMENT 'The business-year-to-date sum of the number of hours, employees have worked in this store up to the equivalent calendar date one year ago.',
	EMP_HR_PY_SWDAY_CNT NUMBER(38,2) COMMENT 'The number of hours, employees have worked in this store on the equivalent weekday one year ago.',
	EMP_HR_PY_SWDAY_BYTD_CNT NUMBER(38,2) COMMENT 'The business-year-to-date sum of the number of hours, employees have worked in this store up to the equivalent weekday one year ago.',
	REAL_ESTATE_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the lifecycle status for real estate objects. (This is the business lifecycle, so it might differ from the status code shown in the source system.)',
	REAL_ESTATE_EVENT_REASON_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the reason why the status of a real estate object has changed. E.g. a store was closed because of lack of expansion options.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	BREAK_START_TM TIME(9) COMMENT 'In case the store closes over lunch time, this is the start time of the break.',
	BREAK_END_TM TIME(9) COMMENT 'In case the store closes over lunch time, this is the end time of the break.',
	constraint PK_T_FACT_STORE_OPEN_DAYS primary key (BUS_DT, STORE_SID, REAL_ESTATE_SID)
) WITH ROW ACCESS POLICY #unknown_policy
COMMENT='This fact table shows for each day, if a store is open, and whether this day an be counted for revenue comparison (bereinigte Steigerung). (In case of new stores, the first week needs to be excluded from the comparison.) In addition, this fact tracks various status attributes, as well as the number hours the store was open on that day and the number of hours, employees have worked in this store. '
;